WITH valid AS (SELECT *, LENGTH(channel) AS channel_length, ADD_MONTHS(starts_on, 1) AS starts_on_plus_months FROM promotions WHERE ends_on > DATE '2023-07-25') SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, channel_length, starts_on_plus_months, FIRST_VALUE(channel_length) IGNORE NULLS OVER (ORDER BY starts_on_plus_months, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_channel_length, COUNT(channel_length) OVER (PARTITION BY channel, promo_code) AS channel_count_channel_length, SUM(discount_pct) OVER (PARTITION BY promo_code) AS promo_code_sum_discount_pct FROM valid;
